(  
  /*
    $input = Array Of Input Object Spec:
    {
      "workOrderId": "2024002T::371",
      "workcenterId": "cnc",
      "calendarId": "cnc",
      "totalDurationMs": 28800000,
      "durationMs": 28800000,
      "earliestStart": "2022-09-08T18:54:55.665Z"
    }
  */
  $input := [$];  

  /*
    $getDurationOfEvent - Returns the duration of an event
    $event - Fuuz Calendar Event Object
    $earliestStart - Date
    @returns - Float
  */
  $getDurationOfEvent := function($event,$earliestStart) {
    (
       /* The logic here fixes slicing issues where we only really want to pickup an event if it's start is  */
       $start := $moment($earliestStart).isAfter($moment($event.start)) ? $earliestStart : $event.start;
       $moment($event.end).diff($moment($event.start))
    )
  };

  /* 
    $sliceArrayAfter - Returns a newly sliced array removing up until $firstIndex
    $arr - Array | Array to Slice
    $firstIndex - Integer | First Index to Retain
    $returns Array
  */
  $sliceArrayAfter := function($arr,$firstIndex) {
    $arr[[$firstIndex..$count($arr)]]
  };

  /*
    $getRemainingDuration - Returns the remaining duration in MS after the durationUsed was applied
    $totalDuration - Float
    $durationUsed - Float
    @returns - Float
  */
  $getRemainingDuration := function($totalDuration, $durationUsed) {
    (
      $remainder := $totalDuration - $durationUsed;
      $remainder > 0 ? $remainder : 0;
    )
  };

  /* 
    $getEventsInRange - Returns events that are the same or before the $earliestStart
    $events - Array<Object> | $getAvailabilityBetween Calendar Events (Not Full Calendar Events)
    $earliestStart - Date | The start of the date range
    @returns - Array<Object>
  */
  $getEventsInRange := function($events,$earliestStart) {
    (
      $earliestStart := $moment($earliestStart);
      $filter([$events],function($v){
        (
          $start := $moment($v.start);
          $end := $moment($v.end);

          $earliestStart.isSameOrBefore($start);
        )
      })
    )
  };

  /* 
    $sliceEventByEarliestStart - Slices an event into two if the earliest start is between the event range returning a newEvent and updatedEvent. The newEvent is the front slice and updatedEvent is the back slice.
    $event - Object | $getAvailabilityBetween Calendar Events (Not Full Calendar Events)
    $earliestStart - Date
    @returns Object { "newEvent": Object, "updatedEvent": Object }
  */
  $sliceEventByEarliestStart := function($event,$earliestStart) {
    (
      $earliestStartM := $moment($earliestStart);
      $eventStartM := $moment($event.start);
      $eventEndM := $moment($event.end);

      $earliestStartM.isBetween($eventStartM,$eventEndM) ? 
      (
         $startDiff := $moment($eventStartM).diff($earliestStartM);
        {
          /* New Event */
          "newEvent": $merge([
            $event,
            {
              "start": ($moment($eventStartM).add($startDiff))[0],
              "end":  $earliestStartM
            }
          ]),
          /* Updated Event */
          "updatedEvent": $merge([
            $event,
            {
              "start":  $earliestStartM
            }
          ])
        }
      )
      /* 
        If the earliestStart isn't between the events we just return undefined. 
        This function will only be used to add/update events in $avail to leave the slot that wasn't available
        To this job to be available to another job that could come along with an earlier start.
      */
    )
  };

  /* 
    $sliceEventsByEarliestStart - Maps over the $events and slices events.
    $events - Array | $getAvailabilityBetween Calendar Events (Not Full Calendar Events)
    $earliestStart - Date
    @returns - Array<Object>
  */
  $sliceEventsByEarliestStart := function($events,$earliestStart) {
    $events.(
      $event := $;
      $sliceEventByEarliestStart($event,$earliestStart)
    )
  };

  /* 
    $updateCalendarEventsForEarliestStart - Updates Calendar Events Array of Objects with the newly created events and updates the prior event to shift it.
    $calendars - Array<Object> | Fuuz Calendars
    $calendarId - String | Fuuz Calendar ID
    $index - Integer | The index the event is located at (This should generally be 0)
    $newEvents - Object {"newEvent": Object, "updatedEvent": Object}
    @returns - Array<Object> | Fuuz Calendars
  */
  $updateCalendarEventsForEarliestStart := function($calendars,$calendarId,$index,$newEvents) {
    (
      $isNilOrEmpty($newEvents.updatedEvent) or $isNilOrEmpty($newEvents.newEvent) ? $calendars : (
        $calendars~>| $[id = $calendarId] | (
          $curCalendar := calendar;
          {
            "calendar": [
              $newEvents.newEvent,
              $curCalendar~>| $[$index] | {
                "start": $newEvents.updatedEvent.start
              }|
            ]
          }
        )|
      )
    )
  };

  /* 
      $scheduleEvent - Finds how much duration we can take from a calendar event and then schedules it. Updating the calendar event to remove the time that was used.
      $avail - Array<Object> | Fuuz Calendar Objects
      $schedulingParams - Object | The Object spec matches $input
      @returns - Object | {"metadata": Object, "schedulingParams": Object, "avail": Object }
  */
  $scheduleEvent := function($avail,$schedulingParams) {
    (
       $calendarEventIndex := 0;
       $calendar := $avail[id = $schedulingParams.calendarId];

       /* If the earliestStart is later than the start we need to slice the event so we can have that there later in the event it's needed */
       $newEvents := $sliceEventsByEarliestStart($calendar.calendar,$schedulingParams.earliestStart);
       /* We now need to overwrite $avail with the new calendar that includes the new event as well as the updated event for where the slice took place */
       $avail := $updateCalendarEventsForEarliestStart($avail,$schedulingParams.calendarId,0,$newEvents);

       /* If we had to slice the events into new events we have to increase the index as the event we used is now index 1 in the calendar event array */
       $calendarEventIndex := $isNilOrEmpty($newEvents) ? $calendarEventIndex : $calendarEventIndex + 1;
       /* Rebind $calendar with the new events that include the split events from $newEvents if they exist */
       $calendar := $avail[id = $schedulingParams.calendarId];
       /* $availableEvents will return a list of events that start after $schedulingParams.earliestStart */
       $availableEvents := $getEventsInRange($calendar.calendar,$schedulingParams.earliestStart);

       $event := $availableEvents[0];
       $maxDuration := $getDurationOfEvent($event,$earliestStart);

       $eventConsumed := $schedulingParams.durationMs >= $maxDuration;
       $durationUsed := $eventConsumed ? $maxDuration : $schedulingParams.durationMs;

       {
         "metadata": {
           "maxDuration": $maxDuration,
           "durationUsed": $durationUsed,
           "eventConsumed": $eventConsumed,
           "eventStart": $event.start,
           "eventEnd": $event.end,
           "calendar": $calendar,
           "newEvents": $newEvents
         },
         "schedulingParams": $merge(
           [
             $schedulingParams,
             {    
               /* If the calendar cannot fulfill this entire event, we will return the remaining durationMs here. */
               "durationMs": $event.groupEventType = "unallocated" ? $schedulingParams.durationMs : $getRemainingDuration($schedulingParams.durationMs, $durationUsed),
               "events": [
                 $schedulingParams.events,
                 $durationUsed > 0 ? {
                   "start": $event.start,
                   "end": ($moment($event.start).add($durationUsed,'milliseconds'))[0],
                   "groupEventType": $event.groupEventType,
                   "durationMs": $durationUsed
                 }
               ]
             }
           ]
         ),
         "avail": (
            (
             $avail~>| $[id = $schedulingParams.calendarId] | (  
                 $eventConsumed = false ? (
                   $~>| calendar[$calendarEventIndex] | {
                       "start": ($moment($event.start).add($durationUsed,'milliseconds'))[0]
                   }|
                 )
                 :
                {
                  "calendar": [ $sliceArrayAfter([calendar], $calendarEventIndex + 1) ]
                }
             )|
           )
         )
       };
    )
  };

  /*
    Recursion

    $recurse($calendars,$inputs,$index) {
      Protection cases for null/undefined values to auto return

      If $inputs[$index] is defined
        $result := $scheduleEvent($calendars,$inputs[$index]);
        $eventDone := $result.schedulingParams.durationMs <= 0;
        $newInputs := $inputs~>| $[$index] | $result.schedulingParams |;
        $recurse($result.avail,$newInputs,$eventDone ? $index + 1 : $index);
    }
  */
  $maxLoops := 1000;
  $returnAcc := false;
  $returnAvail := false;

  $recurse := function($calendars,$schedulingParamsArr,$index,$loopCounter,$acc) {
    $loopCounter > $maxLoops ? {
      "type": "Loop Counter Over " & $maxLoops,
      "results": $schedulingParamsArr,
      "acc": $returnAcc ? $acc,
      "avail": $returnAvail ? $calendars
    } :
    $isNilOrEmpty($calendars) ? {
      "type": "No Calendars",
      "results": $schedulingParamsArr,
      "acc": $returnAcc ? $acc,
      "avail": $returnAvail ? $calendars
    } :
    $isNilOrEmpty($schedulingParamsArr[$index]) ? {
      "type": "No Scheduling Params At Index: " & $index,
      "results": $schedulingParamsArr,
      "acc": $returnAcc ? $acc,
      "avail": $returnAvail ? $calendars
    } :
    $isNilOrEmpty($index) ? {
      "type": "Index is Nil Or Empty",
      "results": $schedulingParamsArr,
      "acc": $returnAcc ? $acc,
      "avail": $returnAvail ? $calendars
    } :
    $isNilOrEmpty($schedulingParamsArr[$index])~>$not ? (
      $schedulingParam := $schedulingParamsArr[$index];

      $schedulingParam.durationMs > 0 or $count($calendars[id = $schedulingParam.calendarId].calendar) > 0 ? (
        $result := $scheduleEvent($calendars,$schedulingParam);
        /* Remaining Duration Of the Event is <= 0 OR There are no Calendar Events For the Calendar Left to Schedule On */
        $eventCompletedScheduling := $result.schedulingParams.durationMs <= 0 or $count($result.avail[id = $schedulingParam.calendarId].calendar) = 0;
        $newSchedulingParamsArr := $schedulingParamsArr~>| $[$index] | $result.schedulingParams |;

        $recurse(
          $result.avail,
          $newSchedulingParamsArr,
          $eventCompletedScheduling ? $index + 1 : $index,
          $loopCounter + 1,
          [$acc,$result]
        );
      )
      :
      $recurse(
        $calendars,
        $schedulingParamsArr,
        $index + 1,
        $loopCounter + 1,
        [
          $acc,
          {
            "type": "Cannot Schedule", "results": $schedulingParamsArr[$index] 
          }
        ]
      );
    )
    :
    {
      "type": "Matched no case",
      "results": $schedulingParamsArr,
      "acc": $returnAcc ? $acc,
      "avail": $returnAvail ? $calendars
    }
  };

  $recurse($state.context.calendars,$input,0,0);
  /* .(
    acc
  ); */
